+                    }
+                    Files.move(tmpPath, filePath, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
+                } else {
+                    Files.move(tmpPath, filePath, StandardCopyOption.ATOMIC_MOVE);
+                }
+            }
+            Files.deleteIfExists(tmpPath);
+        }
+    }
